1	export type Cell = [number, number];
2	
3	const SURVIVING_NEIGHBOUR_COUNTS = [2, 3];
4	const BIRTH_NEIGHBOUR_COUNT = 3;
5	
6	function isSameCell([x, y]: Cell, [otherX, otherY]: Cell): boolean {
7	  return x === otherX && y === otherY;
8	}
9	
10	function isAdjacent([x, y]: Cell, [otherX, otherY]: Cell): boolean {
11	  return Math.abs(otherX - x) <= 1 && Math.abs(otherY - y) <= 1;
12	}
13	
14	function isNeighbourOf(cell: Cell, other: Cell): boolean {
15	  return isAdjacent(cell, other) && !isSameCell(cell, other);
16	}
17	
18	function countLivingNeighbours(cell: Cell, livingCells: Cell[]): number {
19	  return livingCells.filter((other) => isNeighbourOf(cell, other)).length;
20	}
21	
22	function survives(cell: Cell, livingCells: Cell[]): boolean {
23	  return SURVIVING_NEIGHBOUR_COUNTS.includes(
24	    countLivingNeighbours(cell, livingCells),
25	  );
26	}
27	
28	function isBorn(cell: Cell, livingCells: Cell[]): boolean {
29	  return countLivingNeighbours(cell, livingCells) === BIRTH_NEIGHBOUR_COUNT;
30	}
31	
32	function isAlive(cell: Cell, livingCells: Cell[]): boolean {
33	  return livingCells.some((living) => isSameCell(cell, living));
34	}
35	
36	const OFFSETS = [-1, 0, 1];
37	
38	/** The 3x3 block centred on the cell: the cell itself plus its 8 neighbours. */
39	function cellAndItsNeighbours([x, y]: Cell): Cell[] {
40	  return OFFSETS.flatMap((dx) => OFFSETS.map((dy): Cell => [x + dx, y + dy]));
41	}
42	
43	function positionKey([x, y]: Cell): string {
44	  return `${x},${y}`;
45	}
46	
47	function deduplicateByPosition(cells: Cell[]): Cell[] {
48	  const byPosition = new Map(cells.map((cell) => [positionKey(cell), cell]));
49	  return [...byPosition.values()];
50	}
51	
52	function cellsThatCouldBeAliveNext(livingCells: Cell[]): Cell[] {
53	  return deduplicateByPosition(livingCells.flatMap(cellAndItsNeighbours));
54	}
55	
56	function isAliveNextGeneration(cell: Cell, livingCells: Cell[]): boolean {
57	  return isAlive(cell, livingCells)
58	    ? survives(cell, livingCells)
59	    : isBorn(cell, livingCells);
60	}
61	
62	export function nextGeneration(livingCells: Cell[]): Cell[] {
63	  return cellsThatCouldBeAliveNext(livingCells).filter((cell) =>
64	    isAliveNextGeneration(cell, livingCells),
65	  );
66	}
